import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Fused GELU kernel - combines all GELU operations into a single kernel
gelu_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void fused_gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        // GELU: 0.5 * x * (1.0 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        const float sqrt_2_over_pi = 0.7978845608028654f;
        float val_cubed = val * val * val;
        float inner = sqrt_2_over_pi * (val + 0.044715f * val_cubed);
        out[idx] = 0.5f * val * (1.0f + tanhf(inner));
    }
}

torch::Tensor fused_gelu_hip(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::empty_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_gelu_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

# Fused LayerNorm kernel
layernorm_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Each block handles one row (one token's embedding)
__global__ void fused_layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int batch_seq,
    int hidden_dim,
    float eps
) {
    extern __shared__ float shared[];

    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= batch_seq) return;

    const float* row_x = x + row * hidden_dim;
    float* row_out = out + row * hidden_dim;

    // Compute mean and variance in parallel
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = tid; i < hidden_dim; i += blockDim.x) {
        float val = row_x[i];
        sum += val;
        sum_sq += val * val;
    }

    // Warp-level reduction
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        sum += __shfl_down(sum, offset);
        sum_sq += __shfl_down(sum_sq, offset);
    }

    // Store warp results in shared memory
    int warp_id = tid / warpSize;
    int lane_id = tid % warpSize;
    int num_warps = (blockDim.x + warpSize - 1) / warpSize;

    if (lane_id == 0) {
        shared[warp_id] = sum;
        shared[warp_id + num_warps] = sum_sq;
    }
    __syncthreads();

    // Final reduction in first warp
    if (warp_id == 0) {
        sum = (tid < num_warps) ? shared[tid] : 0.0f;
        sum_sq = (tid < num_warps) ? shared[tid + num_warps] : 0.0f;

        for (int offset = warpSize / 2; offset > 0; offset /= 2) {
            sum += __shfl_down(sum, offset);
            sum_sq += __shfl_down(sum_sq, offset);
        }

        if (tid == 0) {
            shared[0] = sum / hidden_dim;  // mean
            float var = sum_sq / hidden_dim - shared[0] * shared[0];
            shared[1] = rsqrtf(var + eps);  // inv_std
        }
    }
    __syncthreads();

    float mean = shared[0];
    float inv_std = shared[1];

    // Normalize and scale
    for (int i = tid; i < hidden_dim; i += blockDim.x) {
        float val = row_x[i];
        row_out[i] = (val - mean) * inv_std * gamma[i] + beta[i];
    }
}

torch::Tensor fused_layernorm_hip(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float eps) {
    auto sizes = x.sizes();
    int batch_seq = 1;
    for (int i = 0; i < sizes.size() - 1; i++) {
        batch_seq *= sizes[i];
    }
    int hidden_dim = sizes[sizes.size() - 1];

    auto out = torch::empty_like(x);

    int block_size = 256;
    int num_warps = (block_size + 63) / 64;
    int shared_mem = num_warps * 2 * sizeof(float);

    fused_layernorm_kernel<<<batch_seq, block_size, shared_mem>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_seq,
        hidden_dim,
        eps
    );

    return out;
}
"""

# Combined source
