from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# C++ declarations for binding
cpp_source = """
#include <torch/extension.h>

torch::Tensor fused_gelu_hip(torch::Tensor x);
torch::Tensor fused_layernorm_hip(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float eps);
"""

# Combined HIP source
hip_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void fused_gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        const float sqrt_2_over_pi = 0.7978845608028654f;
        float val_cubed = val * val * val;
        float inner = sqrt_2_over_pi * (val + 0.044715f * val_cubed);
        out[idx] = 0.5f * val * (1.0f + tanhf(inner));
    }
}

torch::Tensor fused_gelu_hip(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::empty_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_gelu_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}

__global__ void fused_layernorm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int batch_seq,
    int hidden_dim,
    float eps
) {
    extern __shared__ float shared[];

    int row = blockIdx.x;
    int tid = threadIdx.x;

    if (row >= batch_seq) return;

    const float* row_x = x + row * hidden_dim;
    float* row_out = out + row * hidden_dim;

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = tid; i < hidden_dim; i += blockDim.x) {
        float val = row_x[i];
        sum += val;
        sum_sq += val * val;
    }

    // Warp-level reduction using __shfl_down
    for (int offset = 32; offset > 0; offset /= 2) {
        sum += __shfl_down(sum, offset);
        sum_sq += __shfl_down(sum_sq, offset);
    }

    int warp_id = tid / 64;
    int lane_id = tid % 64;
    int num_warps = (blockDim.x + 63) / 64;

    if (lane_id == 0) {
        shared[warp_id] = sum;
        shared[warp_id + num_warps] = sum_sq;
    }
    __syncthreads();

    if (warp_id == 0 && tid < num_warps) {
        sum = shared[tid];
        sum_sq = shared[tid + num_warps];

        for (int offset = 32; offset > 0; offset /= 2) {
            sum += __shfl_down(sum, offset);
            sum_sq += __shfl_down(sum_sq, offset);
        }

        if (tid == 0) {
            shared[0] = sum / hidden_dim;
            float var = sum_sq / hidden_dim - shared[0] * shared[0];
            shared[1] = rsqrtf(var + eps);
        }
    }
    __syncthreads();

    float mean = shared[0];
    float inv_std = shared[1];

    for (int i = tid; i < hidden_dim; i += blockDim.x) {
        float val = row_x[i];
        row_out[i] = (val - mean) * inv_std * gamma[i] + beta[i];
    }
}

torch::Tensor fused_layernorm_hip(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float eps) {
    auto sizes = x.sizes();
    int batch_seq = 1;
    for (size_t i = 0; i < sizes.size() - 1; i++) {
        batch_seq *= sizes[i];
    }
    int hidden_dim = sizes[sizes.size() - 1];

    auto out = torch::empty_like(x);

    int block_size = 256;
    int num_warps = (block_size + 63) / 64;
    int shared_mem = num_warps * 2 * sizeof(float);

    fused_layernorm_kernel<<<batch_seq, block_size, shared_mem>>>(
        x.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_seq,
        hidden_dim,
        eps
    );

    return out;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=cpp_source,
    cuda_sources=hip_source,
    functions=["fused_gelu_hip", "fused_layernorm_hip"],
    verbose=True,
    extra_cuda_cflags=["-O3"]
)


class NewGELU(nn.Module):
    def __init__(self):
        super(NewGELU, self).__init__()

    def forward(self, x):
        return fused_ops.fused_gelu_hip(x)


class FusedLayerNorm(nn.Module):
    def __init__(self, normalized_shape, eps=1e-5):
        super().__init__()
        self.eps = eps
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))

    def forward(self, x):
        return fused_ops.fused_layernorm_hip(x, self.weight, self.bias, self.eps)


class CausalSelfAttention(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd

    def forward(self, x):
        B, T, C = x.size()

        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
        att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))
        att = F.softmax(att, dim=-1)
        att = self.attn_dropout(att)
        y = att @ v
        y = y.transpose(1, 2).contiguous().view(B, T, C)

        y = self.resid_dropout(self.c_proj(y))
        return y


class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = FusedLayerNorm(n_embd)
        self.attn = CausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = FusedLayerNorm(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = NewGELU(),
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x))))

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x


