#include <hip/hip_runtime.h>
#include <torch/extension.h>

// Fused kernel for reshaping attention output from [B, nh, T, hs] to [B, T, C]
// Uses vectorized loads when possible
__global__ void fused_output_reshape_kernel(
    const float* __restrict__ input,    // [B, nh, T, hs]
    float* __restrict__ output,          // [B, T, C]
    int B, int T, int nh, int hs
) {
    int C = nh * hs;
    int total = B * T * C;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total) return;

    // Decode output index: [b, t, c] where c = h * hs + s
    int c = idx % C;
    int t = (idx / C) % T;
    int b = idx / (C * T);

    int h = c / hs;
    int s = c % hs;

    // Input index in [B, nh, T, hs] format
    int in_idx = b * nh * T * hs + h * T * hs + t * hs + s;

    output[idx] = input[in_idx];
}

torch::Tensor fused_output_reshape_hip(torch::Tensor input, int B, int T, int C) {
    auto output = torch::empty({B, T, C}, input.options());

    int total = B * T * C;
    int block_size = 256;
    int num_blocks = (total + block_size - 1) / block_size;

    int nh = input.size(1);
    int hs = input.size(3);

    fused_output_reshape_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        B, T, nh, hs
    );

