class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.ln_1 = FusedLayerNormResidual(n_embd)
        self.attn = CausalSelfAttention(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = FusedLayerNormResidual(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = NewGELU(),
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x))))

    def forward(self, x):
        # Create zero residual for first layer norm (to match original behavior)
        zero_residual = torch.zeros_like(x)

        # First: LayerNorm -> Attention -> Add residual
        ln1_out = self.ln_1(x, zero_residual)  # LayerNorm(x + 0) = LayerNorm(x)
        attn_out = self.attn(ln1_out)
        x = x + attn_out

        # Second: LayerNorm -> MLP -> Add residual
        ln2_out = self.ln_2(x, zero_residual)  # LayerNorm(x)
        mlp_out = self.mlpf(ln2_out)
        x = x + mlp_out

        return x


