// Fused bias add + GELU activation
__global__ void fused_bias_gelu_kernel_vec4(
    const float4* __restrict__ x,
    const float* __restrict__ bias,
    float4* __restrict__ out,
    int hidden_dim,
    int size4
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size4) {
        float4 val = x[idx];
        int base_idx = idx * 4;

        const float sqrt_2_over_pi = 0.7978845608028654f;

        float4 result;
        float v, v3, inner;

        // Add bias (broadcast across batch*seq dimension)
        v = val.x + bias[(base_idx + 0) % hidden_dim];
        v3 = v * v * v;
        inner = sqrt_2_over_pi * (v + 0.044715f * v3);
        result.x = 0.5f * v * (1.0f + tanhf(inner));

        v = val.y + bias[(base_idx + 1) % hidden_dim];
        v3 = v * v * v;
        inner = sqrt_2_over_pi * (v + 0.044715f * v3);
        result.y = 0.5f * v * (1.0f + tanhf(inner));

        v = val.z + bias[(base_idx + 2) % hidden_dim];
        v3 = v * v * v;
        inner = sqrt_2_over_pi * (v + 0.044715f * v3);
        result.z = 0.5f * v * (1.0f + tanhf(inner));

        v = val.w + bias[(base_idx + 3) % hidden_dim];
        v3 = v * v * v;
        inner = sqrt_2_over_pi * (v + 0.044715f * v3);
        result.w = 0.5f * v * (1.0f + tanhf(inner));

