torch::Tensor fused_bias_gelu_hip(torch::Tensor x, torch::Tensor bias) {
    auto size = x.numel();
    auto out = torch::empty_like(x);
    int hidden_dim = bias.size(0);

    // Use vectorized version when possible
    if (size % 4 == 0) {
